import React, { useState } from 'react';
import { View, Text, ScrollView, TouchableOpacity, StyleSheet, Modal } from 'react-native';
import { useNavigate } from 'react-router-dom';
import { useTheme } from './theme';
import { useLocale } from './hooks/useLocale';
import { SoundManager } from './sound';
import { Share2, Inbox, Globe, Upload, Swords } from 'lucide-react';

// レスポンシブ判定用フック
const useResponsive = () => {
  const [screenType, setScreenType] = React.useState<'mobile' | 'tablet' | 'desktop'>('mobile');

  React.useEffect(() => {
    const checkScreen = () => {
      const width = window.innerWidth;
      if (width < 640) setScreenType('mobile');
      else if (width < 1024) setScreenType('tablet');
      else setScreenType('desktop');
    };

    checkScreen();
    window.addEventListener('resize', checkScreen);
    return () => window.removeEventListener('resize', checkScreen);
  }, []);

  return screenType;
};

// マルチ機能のハブ画面
export default function MultiHubScreen() {
  const navigate = useNavigate();
  const { colors } = useTheme();
  const locale = useLocale();
  const ja = locale === 'ja';
  const screenType = useResponsive();

  const [showShareOptions, setShowShareOptions] = useState(false);

  // カードの列数を決定
  const getColumns = () => {
    switch (screenType) {
      case 'desktop':
        return 2;
      case 'tablet':
        return 2;
      case 'mobile':
        return 1;
    }
  };

  const menuItems = [
    {
      id: 'share',
      icon: <Share2 size={24} color={colors.primary} />,
      title: ja ? 'コード共有' : 'CODE UPLINK',
      description: ja ? 'コードで送信または受信' : 'Send or receive via code',
      onPress: () => setShowShareOptions(true),
    },
    {
      id: 'public',
      icon: <Globe size={24} color={colors.primary} />,
      title: ja ? '公開問題' : 'PUBLIC NODES',
      description: ja ? '公開中の問題を閲覧' : 'Browse shared public questions',
      onPress: () => navigate('/multi/public'),
    },
    {
      id: 'battle',
      icon: <Swords size={24} color={colors.primary} />,
      title: ja ? 'リアルタイム対戦' : 'BATTLE ARENA',
      description: ja ? 'リアルタイム対戦: 1分で問題を出し合い、回答速度を競う' : 'Live battle: swap questions in 1 min, race to answer',
      onPress: () => navigate('/battle'),
    },
  ];

  return (
    <View style={[styles.container, { backgroundColor: colors.background }]}>
      <View style={[styles.header, { backgroundColor: colors.card, borderBottomColor: colors.border }]}>
        <Text style={[styles.headerTitle, { color: colors.text, letterSpacing: 1 }]}>
          <Share2 size={22} color={colors.primary} style={{ marginRight: 8 }} />共有
        </Text>
      </View>

      <ScrollView contentContainerStyle={[styles.content, { paddingBottom: 100 }]}>
        <View style={[styles.grid, { flexDirection: 'row', flexWrap: 'wrap', gap: 12 }]}>
          {menuItems.map((item) => (
            <TouchableOpacity
              key={item.id}
              style={[
                styles.card,
                {
                  backgroundColor: colors.card,
                  borderColor: colors.border,
                  width: `${100 / getColumns() - 2}%`,
                  flexDirection: 'column',
                  alignItems: 'center',
                  justifyContent: 'center',
                  padding: 16,
                  minHeight: 120,
                },
              ]}
              onPress={() => { SoundManager.play('decide'); item.onPress(); }}
              activeOpacity={0.7}
            >
              <View style={styles.cardIcon}>{item.icon}</View>
              <View style={styles.cardContent}>
                <Text style={[styles.cardTitle, { color: colors.text, textAlign: 'center' }]}>{item.title}</Text>
                <Text style={[styles.cardDescription, { color: colors.textSecondary, textAlign: 'center' }]}>{item.description}</Text>
              </View>
            </TouchableOpacity>
          ))}
        </View>
      </ScrollView>

      {/* 共有方法選択モーダル */}
      <Modal
        visible={showShareOptions}
        transparent
        animationType="fade"
        onRequestClose={() => setShowShareOptions(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContainer, { backgroundColor: colors.card }]}>
            <Text style={[styles.modalTitle, { color: colors.text }]}>
              {ja ? '共有方法を選択' : 'Select share method'}
            </Text>
            <TouchableOpacity
              style={[styles.modalOption, { borderColor: colors.border, backgroundColor: colors.background }]}
              onPress={() => { SoundManager.play('decide'); setShowShareOptions(false); navigate('/multi/share'); }}
              activeOpacity={0.7}
            >
              <Upload size={20} color={colors.primary} />
              <Text style={[styles.modalOptionText, { color: colors.text }]}>
                {ja ? 'コードを生成して送信' : 'Generate code to send'}
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.modalOption, { borderColor: colors.border, backgroundColor: colors.background }]}
              onPress={() => { SoundManager.play('decide'); setShowShareOptions(false); navigate('/inbox'); }}
              activeOpacity={0.7}
            >
              <Inbox size={20} color={colors.primary} />
              <Text style={[styles.modalOptionText, { color: colors.text }]}>
                {ja ? 'コードで受信' : 'Receive via code'}
              </Text>
            </TouchableOpacity>
            <TouchableOpacity
              style={[styles.modalCancelBtn, { borderColor: colors.border }]}
              onPress={() => { SoundManager.play('decide'); setShowShareOptions(false); }}
              activeOpacity={0.7}
            >
              <Text style={[styles.modalCancelText, { color: colors.textSecondary }]}>
                {ja ? 'キャンセル' : 'Cancel'}
              </Text>
            </TouchableOpacity>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  header: { padding: 16, borderBottomWidth: 1 },
  headerTitle: { fontSize: 20, fontWeight: 'bold' },
  content: { padding: 16 },
  grid: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 12,
  },
  card: {
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 16,
    minHeight: 120,
    borderRadius: 12,
    borderWidth: 1,
  },
  cardIcon: {
    marginBottom: 12,
  },
  cardContent: {
    alignItems: 'center',
  },
  cardTitle: {
    fontSize: 16,
    fontWeight: 'bold',
    marginBottom: 4,
    textAlign: 'center',
  },
  cardDescription: {
    fontSize: 13,
    textAlign: 'center',
    lineHeight: 18,
  },
  modalOverlay: {
    flex: 1,
    backgroundColor: 'rgba(0,0,0,0.5)',
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
  },
  modalContainer: {
    width: '100%',
    maxWidth: 400,
    borderRadius: 16,
    padding: 20,
    gap: 12,
  },
  modalTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    textAlign: 'center',
    marginBottom: 8,
  },
  modalOption: {
    flexDirection: 'row',
    alignItems: 'center',
    gap: 12,
    padding: 16,
    borderRadius: 12,
    borderWidth: 1,
  },
  modalOptionText: {
    fontSize: 16,
    flex: 1,
    textAlign: 'center',
  },
  modalCancelBtn: {
    alignItems: 'center',
    paddingVertical: 14,
    borderRadius: 12,
    borderWidth: 1,
    marginTop: 4,
  },
  modalCancelText: {
    fontSize: 15,
  },
});
